impl Mirror for DynamicsDesc {
    const SIZE: u32 = 0x14;

    fn import(m: &Mem, at: u32, cx: &mut dyn Cx) -> Self {
        let _ = (&m, at, &cx);
        DynamicsDesc {
            data: cx.import_data(m.u32(at + 0x0)),
            count: m.u32(at + 0x4),
            pos: Vec3::import(m, at + 0x8, cx),
        }
    }

    fn compare(&self, m: &Mem, at: u32, path: &str, cx: &mut dyn Cx) {
        let _ = (&m, at, path, &cx);
        cx.compare_data(&format!("{path}.data"), self.data, m.u32(at + 0x0));
        if self.count != m.u32(at + 0x4) {
            cx.mismatch(
                &format!("{path}.count"),
                format!("{:?}", self.count),
                format!("{:?}", m.u32(at + 0x4)),
            );
        }
        self.pos.compare(m, at + 0x8, &format!("{path}.pos"), cx);
    }
}

